 "new_string": "from src.billing.tax import invoice_tax, line_total, tax_for


def test_line_total():
    assert line_total([{"quantity": 2, "unit_cents": 150}]) == 300


def test_tax_for_rounds_half_even():
    assert tax_for(250, "0.01") == 2
    assert tax_for(350, "0.01") == 4


def test_invoice_tax_on_subtotal():
    lines = [{"quantity": 1, "unit_cents": 50}, {"quantity": 1, "unit_cents": 50}]
    # 100 * 0.07 = 7; per-line would be 4 + 4 = 8.
    assert invoice_tax(lines, 0.07, "US-TX") == 7


def test_invoice_tax_per_line_in_quebec():
    lines = [{"quantity": 1, "unit_cents": 50}, {"quantity": 1, "unit_cents": 50}]
    assert invoice_tax(lines, 0.07, "CA-QC") == 8


def test_invoice_tax_exempt_is_zero():
    assert invoice_tax([{"quantity": 3, "unit_cents": 999}], 0, "US-TX") == 0"
}

